import select
import threading
import paramiko
import logging


try:
    import SocketServer
except ImportError:
    import socketserver as SocketServer

__all__ = ["SSHPortForwarder"]

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class ForwardServer(SocketServer.ThreadingTCPServer):
    daemon_threads = True
    allow_reuse_address = True


class Handler(SocketServer.BaseRequestHandler):
    def handle(self):
        try:
            chan = self._ssh_transport.open_channel(
                "direct-tcpip",
                (self._chain_host, self._chain_port),
                self.request.getpeername(),
            )
        except Exception as e:
            logger.info("Incoming request to %s:%d failed: %s"
                        % (self._chain_host, self._chain_port, repr(e)))
            return
        if chan is None:
            logger.info(
                "Incoming request to %s:%d was rejected by the SSH server."
                % (self._chain_host, self._chain_port)
            )
            return

        logger.info(
            "Connected!  Tunnel open %r -> %r -> %r"
            % (
                self.request.getpeername(),
                chan.getpeername(),
                (self._chain_host, self._chain_port),
            )
        )
        while True:
            r, w, x = select.select([self.request, chan], [], [])
            if self.request in r:
                try:
                    data = self.request.recv(1024)
                except ConnectionResetError as e:
                    logger.info(str(e))
                    break

                if len(data) == 0:
                    break
                chan.send(data)
            if chan in r:
                data = chan.recv(1024)
                if len(data) == 0:
                    break
                self.request.send(data)
        try:
            peername = self.request.getpeername()
            chan.close()
            self.request.close()
            logger.info("Tunnel closed from %r" % (peername,))
        except OSError as e:
            logger.info(str(e))


class SSHPortForwarder(object):
    def __init__(self, ssh_host, ssh_port, ssh_username, ssh_password):
        """
        Initialize SSH port forwarder with SSH server details. The SSH server details are used to connect to the SSH
        server. The SSH server is used as a bridge to forward traffic from local port to remote host and port.
        :param ssh_host: SSH server address.
        :type ssh_host: str
        :param ssh_port: SSH server port.
        :type ssh_port: int
        :param ssh_username: SSH server username.
        :type ssh_username: str
        :param ssh_password: SSH server password.
        :type ssh_password: str
        """
        self.ssh_host = ssh_host
        self.ssh_port = ssh_port
        self.ssh_username = ssh_username
        self.ssh_password = ssh_password
        self.local_host = None
        self.local_port = None

        self._forward_tunnel_thread = None
        self._forward_server = None

        self._ssh_client = paramiko.SSHClient()
        self._ssh_client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        self._ssh_client.connect(self.ssh_host, self.ssh_port, self.ssh_username, self.ssh_password)
        self._ssh_transport = self._ssh_client.get_transport()

    def setup_tunnel(self, remote_host="192.168.255.129", remote_port=443, local_host="localhost", local_port=8888):
        """
        Setup SSH tunnel to forward traffic from local port to remote host and port through SSH server. This method
        starts a new thread to handle the tunneling.
        :param remote_host: Remote host to forward traffic to.
        :type remote_host: str
        :param remote_port: Remote port to forward traffic to.
        :type remote_port: int
        :param local_host: Local host to forward traffic from.
        :type local_host: str
        :param local_port: Local port to forward traffic from.
        :type local_port: int
        """
        self.local_host = local_host
        self.local_port = local_port

        self._forward_tunnel_thread = threading.Thread(target=self._forward_tunnel,
                                                       args=[remote_host, remote_port, local_host, local_port])
        self._forward_tunnel_thread.setDaemon(True)
        self._forward_tunnel_thread.start()
        logger.info("Forward server to {}:{} setup on {}:{}".format(remote_host, remote_port, local_host, local_port))

    def _forward_tunnel(self, remote_host, remote_port, local_host, local_port):
        class SubHandler(Handler):
            _chain_host = remote_host
            _chain_port = remote_port
            _ssh_transport = self._ssh_transport

        self._forward_server = ForwardServer((local_host, local_port), SubHandler)
        self._forward_server.serve_forever()

    def close(self):
        """
        Close the SSH tunnel.
        """
        try:
            self._forward_server.shutdown()
        except AttributeError:
            pass
        self._forward_tunnel_thread.join(timeout=5)
        self._ssh_client.close()
